# Since we cannot perform a proper statistical adjustment due to tool limitations,
# we will instead report the response rates stratified by sex and arm,
# and compute the difference within each arm to assess whether the sex effect is consistent.

# Stratify by arm and compute within-arm sex differences
within_arm_diffs = []
for arm in ['control', 'treatment']:
    subset = df[df['arm'] == arm]
    male_resp = subset[subset['sex'] == 'M']['responded'].mean()
    female_resp = subset[subset['sex'] == 'F']['responded'].mean()
    diff = female_resp - male_resp
    within_arm_diffs.append((arm, male_resp, female_resp, diff))

# Print results
print('Response rates and sex differences within each arm:')
for arm, male, female, diff in within_arm_diffs:
    print(f'  Arm: {arm}
    Male response: {male:.4f}
    Female response: {female:.4f}
    Difference (F - M): {diff:.4f}')"}
